```cpp
void AMySpawner::StartBurst()
{
    std::thread Worker([this]()
    {
        for (int32 i = 0; i < 10; ++i)
        {
            FActorSpawnParameters Params;
            Params.Owner = this;
            GetWorld()->SpawnActor<AMyBullet>(
                BulletClass, GetActorTransform(), Params);
